-- CA_0150_la_trustee_area_boards_batch4.sql
-- LA-County TRUSTEE-AREA unified school boards, batch 4: Pomona, Temple City, Torrance, Norwalk-La Mirada.
-- Same pattern as CA_0144 / CA_0146 / CA_0149: one X0002 polygon + SCHOOL sub-district per trustee area,
-- dissolved from the LA County Registrar-Recorder precinct layer (Political_Boundaries/MapServer/34,
-- DST_USD/DIV_USD; codes 23 Pomona, 33 Temple City, 37 Torrance, 4 Norwalk-La Mirada); offices move off the
-- whole-district row; stale holders closed (how_ended 'unknown', end date not researched); current
-- members seated from each district's board page with oath dates from its minutes; Nov 3 2026 races.
--
-- BATCH-SPECIFIC:
--   * Seat counts (decision 2026-09-22): Pomona has a 5-member board but the DB held 7 offices -> 2
--     surplus deleted (no race referenced them). Temple City 5 areas / 4 offices -> 1 cloned.
--     Norwalk-La Mirada 7 areas / 5 offices -> 2 cloned.
--   * Torrance areas are LETTERED. RR/CC DIV_USD 1..5 = A..E, verified with anchor points against
--     tusd.org's 2024 trustee-area map (A: Prairie Ave & 190th St -> 1; C: Van Ness & Del Amo -> 3;
--     D: Torrance Airport -> 4; E: Sepulveda & Maple -> 5; B: Anza & Torrance Blvd -> 2).
--   * Coverage tolerance: Torrance's TIGER unified polygon includes ~10.5 km2 of Santa Monica Bay west
--     of the shoreline (no addresses); the precinct-built areas are land only, so the gate allows 20 pct
--     for Torrance (measured 16.6 pct) while still requiring <= 1 pct of area OUTSIDE TIGER.
--   * Torrance Trustee Area D is VACANT: the seat is flagged is_vacant (vacant_since NULL, because the
--     exact resignation day between 2026-07-06 and 2026-07-14 is not published). The Nov 2026 TA D race
--     elects the successor. TA B is a special election (unexpired term to Dec 2028).
--   * Norwalk-La Mirada: members elected at large in 2022 are placed on the trustee area the district's
--     board page lists for their seat. Mark Copland holds the TA 6 seat by provisional appointment but is
--     a (non-incumbent) candidate for TA 5 in Nov 2026; his candidacy is linked to his row.
--   * Reuses NetFile rows for Tamara Gonzalez and Arturo Jimenez (Pomona) and Dave Zygielbaum (Torrance).
BEGIN;

CREATE TEMP TABLE _seat (parent_geo text, geo_id text, label text, ta text, ord int, full_name text, first_name text,
                         last_name text, url text, existing_pid uuid, term_start date, prec text, how text, src text,
                         pin_office uuid, vacant_since date, pid uuid) ON COMMIT DROP;
